INSERT INTO `faq` (`id`, `question`, `answer`, `order_id`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Can I bring my friend along with me for the Photowalk ?', 'Yes you can bring depending upon the slot availabilty. Please ask your friend or family member to register as well so we could know the count.', NULL, 1, '2022-11-26 13:03:25', '2025-01-23 18:38:18', '2025-01-23 18:38:18'),
(2, 'Is there any Fees for attending the Photowalk ?', 'All our photowalks across India are free of cost . Government entry fees applies incase of heritage sites participant\'s need to pay the entry fees for visiting these site.', NULL, 1, '2022-11-26 13:03:42', '2025-05-27 10:01:28', NULL),
(3, 'I do not have a Camera can I participate in the Photowalk ?', 'Yes surely you can. We provide Fujifilm Mirrorless Cameras for our photowalks that will be shared among the participants. It would be great if you could carry a SD Card, so that you can take back your clicked photographs.', NULL, 1, '2022-12-18 18:20:25', '2022-12-18 18:20:51', NULL),
(4, 'I would like to know more. How can we connect ?', 'For more details please fill the form in your contact us page.\r\nhttps://photowalksindia.com/contact-us', NULL, 1, '2022-12-18 18:24:47', '2023-01-10 11:21:39', NULL);
